 "examples": [
  [
   "範例一：新聞",
   "to-mini",
   "On Saturday the city of Riverdale (a small city in the north of the country) opened a new park.\nThe park has a big green area, a small lake and a playground (a place with games for children).\nMore than 300 people came on the first day.\nThe mayor (the person who leads a city) said the park was made because the old park was too small and there were not enough places for children to play.\nNow families in the city can walk to the park in 10 minutes.\nThe city plans to build 2 more parks before the end of 2027."
  ],
  [
   "範例二：說明文（怎麼煮好一杯茶）",
   "to-mini",
   "Good tea is easy to make, but you must follow 4 steps.\nFirst, heat the water until it starts to make small bubbles.\nSecond, put the tea in your cup and wait for 1 minute.\nThird, pour the hot water into the cup. Do not pour all the water, because then the tea will be too strong.\nLast, wait 1 more minute and drink.\nYou can add more water if the tea is too strong for you.\nMany people like to add milk or sugar, but good tea does not need them."
  ],
  [
   "範例三：故事",
   "to-mini",
   "Long ago, a small dog lived in a small village (a small town in the country) near the sea.\nEvery day he looked for food, but the village was poor and there was little to eat.\n1 winter day, the dog was very hungry and very cold.\nHe found a fishing boat (a big boat that people use to catch fish) near the land.\nThe people on the boat gave him fish every day.\nAfter 1 year, the dog was big and strong.\nHe never went back to the village. He slept on the boat and he ate every day, and in the evening he looked at the sea with his old friend."
  ],
  [
   "範例四：對話（在醫院）",
   "to-mini",
   "A: Good morning. What is wrong?\nB: I have a bad cough since Monday, and I feel very tired.\nA: Do you have a fever?\nB: A little. I also have a pain in my throat when I drink cold water.\nA: Let me look at your throat. Your throat is not very bad, but you cannot breathe well through your nose. You have a common cold. You must rest at home for 2 days and drink much water.\nB: Do I need to take medicine?\nA: Yes, take this 2 times a day after you eat. Come back in 3 days if you do not get better.\nB: Thank you, doctor. I will rest."
  ],
  [
   "範例五：科普（天空為什麼是藍的）",
   "to-mini",
   "The sky looks blue because the air is full of very small things that we cannot see.\nWhen white light from the sun comes into the air, these small things send the blue light in all directions much more than the other colors.\nThis is the same reason that the sky is red at sunrise and sunset.\nAt that time the light must go through much more air, so most of the blue light goes away before it reaches your eyes.\nThe light that reaches you is most of all red and orange.\nScientists (people who study how the world works) have studied this for 100 years, and today we can measure it with machines."
  ],
  [
   "範例六：生活（一天的習慣）",
   "to-mini",
   "I have 4 good habits (things you do again and again) that changed my life.\nFirst, I get up at 7 every morning, even on Sunday.\nSecond, I read for 20 minutes before I look at my phone.\nThird, I walk home instead of taking the bus. It takes about 30 minutes.\nLast, I go to bed at 11 and I do not look at my phone after 10.\nThese small things are not hard, but you must do them every day for 2 or 3 months before you see a real change.\nA friend told me that the hardest part is not the first week, but the 100th day."
  ],
  [
   "反向翻譯一：Mini-English → 一般英文",
   "to-mini",
   "Last week I went to the city with my friend Anna (a woman who works with me).\nWe saw a very old building with big windows and a small garden in front of it.\nAnna said it was a museum (a place where people look at old things) of old machines.\nThere were many people there, and we waited 20 minutes for the door.\nIn the end we did not go in, because we were too tired.\nWe went back home and made some food.\nIt was not a very good day, but it was fun."
  ],
  [
   "反向翻譯二：Mini-English → 一般英文",
   "to-mini",
   "If you want to learn English fast, do 3 things.\nFirst, learn 10 new words every day and use them in a sentence.\nSecond, listen to English for 30 minutes every day. Do not just read.\nThird, speak with a person every week, even if you are afraid.\nMany people want to learn a language, but few people keep doing it for 6 months.\nThe people who can speak a new language are not the smart people. They are the people who go on."
  ]
 ],
 "rules": [
  [
   "規則 1　主詞 + 動詞 + 賓語",
   "I eat rice every day.\nShe writes a letter to her friend."
  ],
  [
   "規則 2　be 動詞：am / is / are / was / were",
   "I am a student.\nYou are my friend.\nShe was very tired yesterday."
  ],
  [
   "規則 3　第三人稱單數：動詞加 -s / -es",
   "He goes to work by bus.\nMy mother works in a shop."
  ],
  [
   "規則 4　進行式：be + V-ing",
   "I am eating lunch now.\nThey are waiting for the bus."
  ],
  [
   "規則 5　過去式：規則 -ed；不規則照附錄",
   "I went to the doctor yesterday.\nShe cooked dinner for her family."
  ],
  [
   "規則 6　將來式：will + V",
   "I will call you tomorrow.\nWe will go to the market on Sunday."
  ],
  [
   "規則 7　否定：not / no",
   "I do not like this one.\nThere is no water in the cup."
  ],
  [
   "規則 8　是非問句：be / 助動詞 / do 移到句首",
   "Are you ready?\nDo you live here?\nCan she sing?"
  ],
  [
   "規則 9　wh- 問句：who / what / where / when / why / how / which",
   "Where do you work?\nWhat is this thing for?\nHow much is it?"
  ],
  [
   "規則 10　冠詞：a / an / the",
   "This is a small shop.\nThe shop is on this street.\nI want an apple."
  ],
  [
   "規則 11　所有格：'s",
   "This is my sister's book."
  ],
  [
   "規則 12　複數：-s / -es / -ies；不規則照附錄",
   "2 children play in the park.\nI have many books and 3 pens."
  ],
  [
   "規則 13　形容詞在名詞前；副詞用 -ly 或表內的副詞",
   "She has a very long hair.\nHe runs fast."
  ],
  [
   "規則 14　介系詞：in / on / at / to / for / with / from / by …",
   "I go to work with a friend.\nThe book is on the table."
  ],
  [
   "規則 15　連接詞：and / or / but / because / so / if / when / until / while",
   "I go home because I am tired.\nIf it rains, I will stay at home."
  ],
  [
   "規則 16　比較：more … than / as … as / 最高級",
   "He is taller than me.\nShe runs as fast as her brother."
  ],
  [
   "規則 17　能力與義務：can / must / should / have to",
   "I can swim very well.\nYou must wait here until I come back."
  ],
  [
   "規則 18　數量：many / much / a few / few / some / all / every / half",
   "I have many books and a little water.\nEvery student in my class has a phone."
  ],
  [
   "規則 19　目的：to + V",
   "I go to the market to buy food.\nShe calls me to say hello."
  ],
  [
   "規則 20　存在：there is / there are",
   "There is a book on the table.\nThere are many people in the park."
  ]
 ],
